44: // Generic helper to split fuzz data into usable parts, like ints etc.
45: // Note that it does not throw, instead it sets the data pointer to null
46: // if the input is exhausted.
47: struct FuzzData {
48:   // data may not be null, even if size is zero.
49:   FuzzData(const uint8_t* data,
50:            size_t size) : Data(data),Size(size){}
51:
52:   ///range is inclusive
53:   template<int Min, int Max>
54:   int getInt() {
55:     static_assert (Min<Max,"min must be <max");
56:
57:     // make this constexpr, can't overflow because that is UB and is forbidden
58:     // in constexpr evaluation
59:     constexpr int range=(Max-Min)+1;
60:     constexpr unsigned int urange=range;
61:
62:     // don't use std::uniform_int_distribution, we don't want to pay for
63:     // over consumption of random data. Accept the slightly non-uniform distribution.
64:     if(range<256)
65:       return Min+static_cast<int>(get<uint8_t>()%urange);
66:     if(range<65536)
67:       return Min+static_cast<int>(get<uint16_t>()%urange);
68:
69:     return Min+static_cast<int>(get<uint32_t>()%urange);
70:   }
71:
72:   template<typename T>
73:   T get() {
74:     const auto Nbytes=sizeof(T);
75:     T ret{};
76:     if(Size<Nbytes) {
77:       //don't throw, signal with null instead.
78:       Data=nullptr;
79:       Size=0;
80:       return ret;
81:     }
82:     std::memcpy(&ret,Data,Nbytes);
83:     Data+=Nbytes;
84:     Size-=Nbytes;
85:     return ret;
86:   }
87:
88:   // gets a string view with length in [Min,Max]
89:   template<int Min, int Max>
90:   std::string_view get_stringview() {
91:     static_assert (Min>=0,"Min must be positive");
92:     const int len=getInt<Min,Max>();
93:     const unsigned int ulen=static_cast<unsigned int>(len);
94:     if(ulen<Size) {
95:       std::string_view ret(chardata(),ulen);
96:       Data+=len;
97:       Size-=ulen;
98:       return ret;
99:     }
100:
101:     //mark that there is too little data to fulfill the request
102:     Data=nullptr;
103:     Size=0;
104:
105:     return {};
106:   }
107:
108:   // split the remainder of the data into string views,
109:   std::vector<std::string_view> splitIntoStrings() {
110:     std::vector<std::string_view> ret;
111:     if(Size>0) {
112:       ret=split(chardata(),Size);
113:       // all data consumed.
114:       Data+=Size;
115:       Size=0;
116:     }
117:     return ret;
118:   }
119:
120:   //are we good?
121:   explicit operator bool() const { return Data!=nullptr;}
122:
123:   //we are a URBG
124:   // https://en.cppreference.com/w/cpp/named_req/UniformRandomBitGenerator
125:   //The type G satisfies UniformRandomBitGenerator if    Given
126:   //   T, the type named by G::result_type
127:   //    g, a value of type G
128:   //
129:   //  The following expressions must be valid and have their specified effects
130:   //  Expression   Return type     Requirements
131:   //  G::result_type       T       T is an unsigned integer type
132:   using result_type=uint8_t;
133:   //  G::min()     T       Returns the smallest value that G's operator() may return. The value is strictly less than G::max(). The function must be constexpr.
134:   static constexpr result_type min() {return 0;}
135:   //  G::max()     T       Returns the largest value that G's operator() may return. The value is strictly greater than G::min(). The function must be constexpr.
136:   static constexpr result_type max() {return 255;}
137:   //  g()  T       Returns a value in the closed interval [G::min(), G::max()]. Has amortized constant complexity.
138:   result_type operator()() {
139:     if(Size==0) {
140:       // return something varying, otherwise uniform_int_distribution may get
141:       // stuck
142:       return failcount++;
143:     }
144:     const result_type ret=Data[0];
145:     Data++;
146:     Size--;
147:     return ret;
148:   }
149:   // returns a pointer to data as const char* to avoid those cstyle casts
150:   const char* chardata() const {return static_cast<const char*>(static_cast<const void*>(Data));}
151:   // members
152:   const uint8_t* Data;
153:   size_t Size;
154:   uint8_t failcount=0;
155: };
